223	    useEffect(() => {
224	        let removeOnCloseListener: () => void;
225	        if (isVisible) {
226	            shouldCallHideModalOnUnmount.current = true;
227	            willAlertModalBecomeVisible(true, type === CONST.MODAL.MODAL_TYPE.POPOVER || type === CONST.MODAL.MODAL_TYPE.BOTTOM_DOCKED);
