384	    const animationInProps = useMemo(() => {
385	        // disableAnimationIn applies only to legacy modals. This should be removed once we fully migrate to `reanimated-modal`.
386	        // eslint-disable-next-line @typescript-eslint/prefer-nullish-coalescing
