389	            // Based on: https://github.com/react-native-modal/react-native-modal/issues/191
390	            return {
391	                animationIn: {from: {opacity: 1}, to: {opacity: 1}},
392	                animationInTiming: 0,
393	            };
394	        }
395	
396	        return {
397	            animationIn: animationIn ?? modalStyleAnimationIn,
398	            animationInDelay,
399	            animationInTiming,
400	        };
401	    }, [animationIn, animationInDelay, animationInTiming, disableAnimationIn, modalStyleAnimationIn, shouldUseReanimatedModal, type]);
402	
403	    // In Modals we need to reset the ScreenWrapperOfflineIndicatorContext to allow nested ScreenWrapper components to render offline indicators,
404	    // except if we are in a narrow pane navigator. In this case, we use the narrow pane's original values.
405	    const {isInNarrowPane} = useContext(NarrowPaneContext);
406	    const {originalValues} = useContext(ScreenWrapperOfflineIndicatorContext);
407	    const offlineIndicatorContextValue = useMemo(() => (isInNarrowPane ? (originalValues ?? {}) : {}), [isInNarrowPane, originalValues]);
