1	import type {ReactNode} from 'react';
2	import React from 'react';
3	import type {StyleProp, TextStyle, ViewStyle} from 'react-native';
4	import usePrevious from '@hooks/usePrevious';
5	import useResponsiveLayout from '@hooks/useResponsiveLayout';
6	import useThemeStyles from '@hooks/useThemeStyles';
7	import CONST from '@src/CONST';
8	import type IconAsset from '@src/types/utils/IconAsset';
9	import ConfirmContent from './ConfirmContent';
10	import Modal from './Modal';
11	import type BaseModalProps from './Modal/types';
12	
13	type ConfirmModalProps = {
14	    /** Title of the modal */
15	    title?: string;
16	
17	    /** A callback to call when the form has been submitted */
18	    onConfirm: () => void;
19	
20	    /** A callback to call when the form has been closed */
21	    onCancel?: () => void;
22	
23	    /** A callback to call when backdrop is pressed */
24	    onBackdropPress?: () => void;
25	
26	    /** Modal visibility */
27	    isVisible: boolean;
28	
29	    /** Confirm button text */
30	    confirmText?: string;
31	
32	    /** Cancel button text */
33	    cancelText?: string;
34	
35	    /** Modal content text/element */
36	    prompt?: string | ReactNode;
37	
38	    /** Whether we should use the success button color */
39	    success?: boolean;
40	
41	    /** Is the action destructive */
42	    danger?: boolean;
43	
44	    /** Whether we should disable the confirm button when offline */
45	    shouldDisableConfirmButtonWhenOffline?: boolean;
46	
47	    /** Whether we should show the cancel button */
48	    shouldShowCancelButton?: boolean;
49	
50	    /** Callback method fired when the modal is hidden */
51	    onModalHide?: () => void;
52	
53	    /** Should we announce the Modal visibility changes? */
54	    shouldSetModalVisibility?: boolean;
55	
56	    /** Icon to display above the title */
57	    iconSource?: IconAsset;
58	
59	    /** Fill color for the Icon */
60	    iconFill?: string | false;
61	
62	    /** Icon width */
63	    iconWidth?: number;
64	
65	    /** Icon height */
66	    iconHeight?: number;
67	
68	    /** Should the icon be centered */
69	    shouldCenterIcon?: boolean;
70	
71	    /** Whether to show the dismiss icon */
72	    shouldShowDismissIcon?: boolean;
73	
74	    /** Styles for title container */
75	    titleContainerStyles?: StyleProp<ViewStyle>;
76	
77	    /** Styles for title */
78	    titleStyles?: StyleProp<TextStyle>;
79	
80	    /** Styles for prompt */
81	    promptStyles?: StyleProp<TextStyle>;
82	
83	    /** Styles for icon */
84	    iconAdditionalStyles?: StyleProp<ViewStyle>;
85	
86	    /** Whether to center the icon / text content */
87	    shouldCenterContent?: boolean;
88	
89	    /** Whether to stack the buttons */
90	    shouldStackButtons?: boolean;
91	
92	    /** Whether to reverse the order of the stacked buttons */
93	    shouldReverseStackedButtons?: boolean;
94	
95	    /** Image to display with content */
96	    image?: IconAsset;
97	
98	    /** Styles for the image */
99	    imageStyles?: StyleProp<ViewStyle>;
100	
101	    /**
102	     * Whether the modal should enable the new focus manager.
103	     * We are attempting to migrate to a new refocus manager, adding this property for gradual migration.
104	     * */
105	    shouldEnableNewFocusManagement?: boolean;
106	
107	    /** How to re-focus after the modal is dismissed */
108	    restoreFocusType?: BaseModalProps['restoreFocusType'];
109	
110	    /** Whether the confirm button is loading */
111	    isConfirmLoading?: boolean;
112	
113	    /** Whether to handle navigation back when modal show. */
114	    shouldHandleNavigationBack?: boolean;
115	};
116	
117	function ConfirmModal({
118	    confirmText = '',
119	    cancelText = '',
120	    prompt = '',
121	    success = true,
122	    danger = false,
123	    onCancel = () => {},
124	    onBackdropPress,
125	    shouldDisableConfirmButtonWhenOffline = false,
126	    shouldShowCancelButton = true,
127	    shouldSetModalVisibility = true,
128	    title = '',
129	    iconSource,
130	    onModalHide = () => {},
131	    titleStyles,
132	    iconAdditionalStyles,
133	    promptStyles,
134	    shouldCenterContent = false,
135	    shouldStackButtons = true,
136	    isVisible,
137	    onConfirm,
138	    image,
139	    imageStyles,
140	    iconWidth,
141	    iconHeight,
142	    iconFill,
143	    shouldCenterIcon,
144	    shouldShowDismissIcon,
145	    titleContainerStyles,
146	    shouldReverseStackedButtons,
147	    shouldEnableNewFocusManagement,
148	    restoreFocusType,
149	    isConfirmLoading,
150	    shouldHandleNavigationBack,
151	}: ConfirmModalProps) {
152	    // We need to use isSmallScreenWidth instead of shouldUseNarrowLayout to use the correct modal type
153	    // eslint-disable-next-line rulesdir/prefer-shouldUseNarrowLayout-instead-of-isSmallScreenWidth
154	    const {isSmallScreenWidth} = useResponsiveLayout();
155	    const styles = useThemeStyles();
156	
157	    // Previous state needed for exiting animation to play correctly.
158	    const prevVisible = usePrevious(isVisible);
159	
160	    // Perf: Prevents from rendering whole confirm modal on initial render.
161	    if (!isVisible && !prevVisible) {
162	        return null;
163	    }
164	
165	    return (
166	        <Modal
167	            onClose={onCancel}
168	            onBackdropPress={onBackdropPress}
169	            isVisible={isVisible}
170	            shouldSetModalVisibility={shouldSetModalVisibility}
171	            onModalHide={onModalHide}
172	            type={isSmallScreenWidth ? CONST.MODAL.MODAL_TYPE.BOTTOM_DOCKED : CONST.MODAL.MODAL_TYPE.CONFIRM}
173	            innerContainerStyle={styles.pv0}
174	            shouldEnableNewFocusManagement={shouldEnableNewFocusManagement}
175	            restoreFocusType={restoreFocusType}
176	            shouldHandleNavigationBack={shouldHandleNavigationBack}
177	        >
178	            <ConfirmContent
179	                title={title}
180	                /* Disable onConfirm function if the modal is being dismissed, otherwise the confirmation
181	            function can be triggered multiple times if the user clicks on the button multiple times. */
182	                onConfirm={() => (isVisible ? onConfirm() : null)}
183	                onCancel={onCancel}
184	                confirmText={confirmText}
185	                cancelText={cancelText}
186	                prompt={prompt}
187	                success={success}
188	                danger={danger}
189	                isVisible={isVisible}
190	                shouldDisableConfirmButtonWhenOffline={shouldDisableConfirmButtonWhenOffline}
191	                shouldShowCancelButton={shouldShowCancelButton}
192	                shouldCenterContent={shouldCenterContent}
193	                iconSource={iconSource}
194	                contentStyles={isSmallScreenWidth && shouldShowDismissIcon ? styles.mt2 : undefined}
195	                iconFill={iconFill}
196	                iconHeight={iconHeight}
197	                iconWidth={iconWidth}
198	                shouldCenterIcon={shouldCenterIcon}
199	                shouldShowDismissIcon={shouldShowDismissIcon}
200	                titleContainerStyles={titleContainerStyles}
201	                iconAdditionalStyles={iconAdditionalStyles}
202	                titleStyles={titleStyles}
203	                promptStyles={promptStyles}
204	                shouldStackButtons={shouldStackButtons}
205	                shouldReverseStackedButtons={shouldReverseStackedButtons}
206	                image={image}
207	                imageStyles={imageStyles}
208	                isConfirmLoading={isConfirmLoading}
209	            />
210	        </Modal>
211	    );
212	}
213	
214	ConfirmModal.displayName = 'ConfirmModal';
215	
