228	function deleteContactMethod(contactMethod: string, loginList: Record<string, Login>, backTo?: string) {
229	    const oldLoginData = loginList[contactMethod];
230	
231	    const optimisticData: OnyxUpdate[] = [
232	        {
233	            onyxMethod: Onyx.METHOD.MERGE,
234	            key: ONYXKEYS.LOGIN_LIST,
235	            value: {
236	                [contactMethod]: {
237	                    partnerUserID: '',
238	                    errorFields: null,
239	                    pendingFields: {
240	                        deletedLogin: CONST.RED_BRICK_ROAD_PENDING_ACTION.DELETE,
241	                    },
242	                },
243	            },
244	        },
245	    ];
246	    const successData: OnyxUpdate[] = [
247	        {
248	            onyxMethod: Onyx.METHOD.MERGE,
249	            key: ONYXKEYS.LOGIN_LIST,
250	            value: {
251	                [contactMethod]: null,
252	            },
253	        },
254	    ];
255	    const failureData: OnyxUpdate[] = [
256	        {
257	            onyxMethod: Onyx.METHOD.MERGE,
258	            key: ONYXKEYS.LOGIN_LIST,
259	            value: {
260	                [contactMethod]: {
261	                    ...oldLoginData,
262	                    errorFields: {
263	                        ...oldLoginData?.errorFields,
264	                        deletedLogin: ErrorUtils.getMicroSecondOnyxErrorWithTranslationKey('contacts.genericFailureMessages.deleteContactMethod'),
265	                    },
266	                    pendingFields: {
267	                        deletedLogin: null,
268	                    },
269	                },
270	            },
271	        },
272	    ];
273	
274	    const parameters: DeleteContactMethodParams = {partnerUserID: contactMethod};
275	
276	    API.write(WRITE_COMMANDS.DELETE_CONTACT_METHOD, parameters, {optimisticData, successData, failureData});
277	    Navigation.goBack(ROUTES.SETTINGS_CONTACT_METHODS.getRoute(backTo));
278	}
279	
280	/**
281	 * Clears a contact method optimistically. this is used when the contact method fails to be added to the backend
282	 */
